// Customer delivery photos for the scrolling strip (the photos are stored inside this file).
(function () {
  var PHOTOS = [
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,",
"data:image/jpeg;base64,"
];
  function build() {
    var track = document.querySelector('.customer-track'); if (!track) return;
    PHOTOS.forEach(function (src, i) {
      var card = document.createElement('div'); card.className = 'photo-card';
      var img = new Image(); img.src = src; img.alt = 'Happy customer with their purchase, photo ' + (i + 1); img.decoding = 'async';
      card.appendChild(img); track.appendChild(card);
    });
    // Duplicate the set once so the loop never jumps, then keep a steady speed for any number of photos
    Array.prototype.slice.call(track.children).forEach(function (c) { var k = c.cloneNode(true); k.setAttribute('aria-hidden', 'true'); track.appendChild(k); });
    track.style.animationDuration = Math.max(30, (track.scrollWidth / 2) / 60) + 's';
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', build); else build();
})();